#!/usr/bin/env bash
# pack_for_boards.sh (laptop): pack what the boards need -> deploy_bundle.tgz (about 100 MB)
#   deploy/            scripts (this directory)
#   data/val.csv       validation list (5,810 images) and manifest.json
#   data/images/...    images in val.csv, with relative paths kept (about 87 MB)
#   checkpoints/       the 5 best.pth of runs/final seed 3 (TorchScript is exported on the board; about 160 MB) -- can be skipped with NO_CKPT=1
#   references/        deploy/references/<run>/predictions.csv (CPU fp32 reference predictions, generated by make_references.sh)
# After unpacking on the board: bash deploy/setup_board.sh; then follow deploy/README.md.
set -euo pipefail
cd "$(dirname "$0")/.."
ROOT="datasets/RSCD dataset-1million"
OUT=${OUT:-deploy_bundle.tgz}
CKPT_ROOT=${CKPT_ROOT:-runs/final}   # on the laptop, when checkpoints are unpacked in final_best_pth/, use CKPT_ROOT=final_best_pth/runs/final
STAGE=$(mktemp -d)
mkdir -p "$STAGE/data/images" "$STAGE/checkpoints" "$STAGE/references"
cp datasets/subsets/val.csv datasets/subsets/manifest.json "$STAGE/data/"
echo "copying val images..."
tail -n +2 datasets/subsets/val.csv | cut -d, -f1 | while IFS= read -r rel; do
  mkdir -p "$STAGE/data/images/$(dirname "$rel")"; cp "$ROOT/$rel" "$STAGE/data/images/$rel"
done
if [[ "${NO_CKPT:-0}" != 1 ]]; then
  for d in single_augB_lr1e-3_wd0.01_e50_s3 moe-fixed_R4_lam1.5_sig0.4_aw0_augB_lr1e-3_wd1e-4_e50_s3 \
           moe-schedule_R4_lam1.5_sig0.4_aw0_augB_lr1e-3_wd1e-4_e50_s3 moe-auxfree_R4_lam0_sig0_aw0_augB_lr1e-3_wd1e-4_e50_s3 \
           moe-fuzzy_R4_lam1.5_sig0.4_aw0_augB_lr1e-3_wd1e-4_e50_s3; do
    [[ -f $CKPT_ROOT/$d/best.pth ]] || { echo "[Error] $CKPT_ROOT/$d/best.pth missing (copy the formal best.pth first)"; exit 1; }
    mkdir -p "$STAGE/checkpoints/$d"; cp "$CKPT_ROOT/$d/best.pth" "$STAGE/checkpoints/$d/"
  done
fi
[[ -d deploy/references ]] && cp -r deploy/references/. "$STAGE/references/"
mkdir -p "$STAGE/deploy"; cp deploy/*.py deploy/*.sh deploy/README.md "$STAGE/deploy/"
tar czf "$OUT" -C "$STAGE" .
rm -rf "$STAGE"
ls -lh "$OUT"
